package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.BasicType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MapType.construct(Class<?> rawType, JavaType keyT, JavaType valueT)
 */
public class MapType_construct_TriageGen2Test {

    @Test
    public void testConstruct_Success() {
        // Arrange
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Class<?> rawType = Map.class;
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = typeFactory.constructType(Integer.class);

        // Act
        MapType result = MapType.construct(rawType, keyType, valueType);

        // Assert
        Assert.assertNotNull("Resulting MapType should not be null", result);
        Assert.assertEquals("Raw type should match", rawType, result.getRawClass());
        Assert.assertEquals("Key type should match", keyType, result.getKeyType());
        Assert.assertEquals("Value type should match", valueType, result.getValueType());
    }

    @Test
    public void testConstruct_WithDifferentRawType() {
        // Arrange
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Class<?> rawType = HashMap.class;
        JavaType keyType = typeFactory.constructType(Double.class);
        JavaType valueType = typeFactory.constructType(Boolean.class);

        // Act
        MapType result = MapType.construct(rawType, keyType, valueType);

        // Assert
        Assert.assertNotNull(result);
        Assert.assertEquals(HashMap.class, result.getRawClass());
        Assert.assertEquals(keyType, result.getKeyType());
        Assert.assertEquals(valueType, result.getValueType());
    }

    @Test(expected = NullPointerException.class)
    public void testConstruct_NullRawType_ThrowsException() {
        // Arrange
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = typeFactory.constructType(Integer.class);

        // Act
        // The constructor or internal _bogusSuperClass likely fails on null rawType
        MapType.construct(null, keyType, valueType);
    }

    @Test
    public void testConstruct_NullKeyType() {
        // Arrange
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Class<?> rawType = Map.class;
        JavaType keyType = null;
        JavaType valueType = typeFactory.constructType(Integer.class);

        // Act
        MapType result = MapType.construct(rawType, keyType, valueType);

        // Assert
        Assert.assertNotNull(result);
        Assert.assertNull("Key type should be null", result.getKeyType());
        Assert.assertEquals(valueType, result.getValueType());
    }

    @Test
    public void testConstruct_NullValueType() {
        // Arrange
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Class<?> rawType = Map.class;
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = null;

        // Act
        MapType result = MapType.construct(rawType, keyType, valueType);

        // Assert
        Assert.assertNotNull(result);
        Assert.assertEquals(keyType, result.getKeyType());
        Assert.assertNull("Value type should be null", result.getValueType());
    }

    @Test
    public void testConstruct_ToString() {
        // Arrange
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        MapType mapType = MapType.construct(
                Map.class, 
                typeFactory.constructType(String.class), 
                typeFactory.constructType(Integer.class)
        );

        // Act
        String toString = mapType.toString();

        // Assert
        // toString for MapType usually contains the raw class and types
        Assert.assertTrue("toString should contain class name", toString.contains("Map"));
        Assert.assertTrue("toString should contain key type", toString.contains("String"));
    }
}
